import{_ as t}from"./chunks/a7b3a30358c086b3a39e.CS8YSe9M.js";import{_ as o,a}from"./chunks/1c28d72d13503dcb4764.fzVJBbgC.js";import{_ as i,C as l,o as s,c as n,j as e,a as m,E as c,a5 as h}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"4小时工作日（专注工作改变了我的人生）","description":"","frontmatter":{"title":"4小时工作日（专注工作改变了我的人生）","originalTitle":"The 4-Hour Workday (Focused Work Changed My Life)","date":"2022-12-10","originalUrl":"https://thedankoe.com/letters/the-4-hour-workday-focused-work-changed-my-life/","minutes":14,"sourceHash":"8c234c1a81a523efd0174b6a22d2a2b4c708ff563ae27a801c45e1afabdc0509","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-4-hour-workday-focused-work-changed-my-life/"}]]},"headers":[],"relativePath":"letters/the-4-hour-workday-focused-work-changed-my-life.md","filePath":"letters/the-4-hour-workday-focused-work-changed-my-life.md"}'),g={name:"letters/the-4-hour-workday-focused-work-changed-my-life.md"};function d(f,p,u,k,_,b){const r=l("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"_4小时工作日-专注工作改变了我的人生",tabindex:"-1"},[m("4小时工作日（专注工作改变了我的人生） "),e("a",{class:"header-anchor",href:"#_4小时工作日-专注工作改变了我的人生","aria-label":'Permalink to "4小时工作日（专注工作改变了我的人生）"'},"​")],-1)),c(r),p[1]||(p[1]=h('<p>快速更新：</p><p>Digital Economics（数字经济学）现已向公众开放。你可以随时注册加入（而不必等到2月）。</p><p>你也可以免费下载 Digital Economics 101（数字经济学基础）。这是一个帮你快速跟上新经济步伐的微型课程。</p><p>如果你有兴趣用我经过3年创作者（creator）经验打磨出的<em>系统</em>将自己产品化，可以考虑加入。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">查看 Digital Economics。</a></p><hr><p><a href="https://www.youtube.com/embed/aV4jKPFOjvk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我在大学里试图成为一名健身YouTuber（没错，就是这个）时，我记得看到了蒂姆·费里斯（Tim Ferriss）写的一本畅销书的书名。</p><p><em>每周工作4小时（The 4-Hour Work Week）。</em></p><p>我从未读过这本书，但出于某种奇怪的原因，我把它理解成了“每天工作4小时”。</p><p>在我的整个大学时期以及我那数不胜数的商业失败中，每天工作4小时的想法一直萦绕在我的脑海里。</p><p>在潜意识里，我做决定时总是把每天的工作时间限制在4小时以内。</p><p><em>单单是这一点，就改变了我的人生方向。</em></p><p>为什么？</p><p><strong>首先</strong>，我认为任何超过4小时的工作都是一个问题。</p><p>很少有人这么做。大多数人把这种生活方式贴上“不可能”的标签，然后它就真的变得不可能了。</p><p>这迫使我的大脑去寻找一个创造性的解决方案，来消除、系统化或自动化低杠杆（leverage）的工作。</p><p>在商业上，这意味着外包、产品化或建立更多的杠杆——所以我就是这么做的。</p><p>我在社交媒体上成长，从极其耗时的客户工作中抽身转型，并将我的服务产品化，以便它们能在我睡觉时卖出去（借助我建立的杠杆）。</p><p>而到了现在，我正在加班。</p><blockquote><p>4小时工作日是一种恩赐，但有时你需要一场16小时极度专注、废寝忘食的马拉松，来看看自己究竟能创造出什么。</p><p>— 丹·柯伊（DAN KOE）（@thedankoe） <a href="https://twitter.com/thedankoe/status/1465612082112602112?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年11月30日</a></p></blockquote><p>在过去的3年里，我有90%的时间每天工作不到4小时。</p><p>最近，我的月收入创下了新高，但如果只工作4小时，这是不可持续的。</p><p>而且，我开始开发一款需要我投入更多精力的新软件。</p><p>但是，你特么（bet your a**）大可放心，我一直在不断思考创造性的方法来减少我的时间开销（同时保持我所创造事物的价值）。</p><p><strong>其次</strong>，就像我们在这些信件中一贯探讨的那样，事情远比“4小时专注工作”要深奥得多。</p><p>所以，让我们深入探讨一下哲学、进化心理学，以及它们为什么对未来的工作——特别是在新数字经济中——至关重要。</p><p>然后，在这封信的末尾，我们将进入我关于专注工作的10大戒律。</p><p><strong>前言</strong>：如果你没有4个小时可以投入到你的事业中，你可以把这些原则应用到你当前的工作中……或者应用到你仅有的1到2个小时的事业时间里。</p><h2 id="利用让我们与众不同的优势" tabindex="-1">利用让我们与众不同的优势 <a class="header-anchor" href="#利用让我们与众不同的优势" aria-label="Permalink to &quot;利用让我们与众不同的优势&quot;">​</a></h2><p>有很多东西让人类在其他生物中脱颖而出。</p><p>比如我们在概念层面上生存，而动物在物理层面上生存。（你不会看到一条蛇因为不同意你的观点而感到受到威胁。）</p><p>但是，一直让我着迷的一个区别是人类的<em>专注深度</em>。</p><p>在心理学中，有任务正激活网络（Task Positive Network）和默认模式网络（Default Mode Network）。</p><p>当我们的注意力聚焦于一系列外部目标或任务时，任务正激活网络就会“启动”。</p><p>这对提高生产力很有帮助。</p><p>当我们的注意力转向内部并向外扩展，从而让更多的想法和观点进入我们的意识时，默认模式网络就会启动。</p><p>这对发挥创造力很有帮助。</p><p>（记住这些，稍后会用到）。</p><p>但是，这道神秘的专注力光谱也有其消极的一面。</p><p><img src="'+t+'" alt=""></p><p>比如当你聚焦于一个问题，而它随之膨胀占据了你所有的注意力。这会让你的大脑对潜在的创造性解决方案闭门不见。一个小问题很快就会变成你的整个世界。</p><p>或者，当你敞开专注力，在意识中同时容纳多个想法时。</p><p>如果这些想法没有关联、缺乏秩序，或者根本说不通——混乱就会随之而来。你可能会被卷入不知所措和焦虑的下行螺旋，难以看清自己所制造的问题泡沫之外的世界。</p><p>这种现象不仅发生在思想中。</p><p>我们的身体也会随之反应。</p><p>你可以通过用指尖触摸某物，来收缩、紧绷或加深你身体存在的焦点。</p><p>你可以通过自信地舒展身体，来敞开、扩张或拓宽你身体存在的焦点。</p><p>就像我们可以投掷飞镖并正中靶心一样，我们也可以为了未来的愿景采取行动。</p><p>前提是你具备让该愿景成为现实的技能、清晰度和意识。因为这可能会很快让你感到不知所措，从而导致拖延。</p><p>最后一个例子：</p><p>我们可以收缩或拓宽我们的视角或世界观。</p><p>根据我们应对不同情况的方式，我们可以是“开放心态”或“封闭心态”。</p><p>你可以敞开心扉去接受只工作4小时甚至更少的想法——或者你也可以放弃，寻找借口，把责任推给除了你自己以外的所有人，直到你妥协为止。</p><h2 id="生存系统" tabindex="-1">生存系统 <a class="header-anchor" href="#生存系统" aria-label="Permalink to &quot;生存系统&quot;">​</a></h2><blockquote><p>进化是强加给我们的，因为随着时间的推移，系统如果不变得更高效，就会土崩瓦解。我们不能停留在原地；即使是为了保持静止，我们也必须前进。—— 米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>作为人类，我们天生就渴望得到更多。</p><p>我们<em>需要</em>不惜一切代价生存下去。</p><p>进化反映了这一点。</p><p>凭借我们独特的心智，我们构建系统来辅助生存。</p><p>挑水和犁地需要消耗大量的能量，所以我们构建了能够高效利用这种能量的系统。</p><p>（灌溉系统、拖拉机，以及为了让这些事情成为可能而必须建立的所有其他系统）。</p><p>系统层层叠加，让我们的大脑变得更高效。我们变得越来越擅长“投资”我们的精神能量。</p><p>让我向你介绍宇宙的最高法则：</p><p><em>熵。</em></p><p>有人称之为“自然税”。</p><p>简而言之，熵是系统中无序程度的量度。</p><p>随着时间的推移，维持一个系统的能量会消散，系统也会瓦解成混乱（除非加入优质的能量）。</p><p>就像图书馆与你家里的藏书相比一样。</p><p>图书馆是系统化的。</p><p>它高效地利用能量来进行按首字母排序、整理，让读者很容易找到书架上的书。</p><p>图书馆有维护这个系统的工作人员，并且有朝一日，我们可能会制造出一个能把这项工作做得更好的机器人（同时节省诸如时间、金钱以及图书馆管理人员脑力带宽等能量）。</p><p>你家里的藏书可能是有条理的，但是当你拿出一本书时会发生什么？读完后你会放回去吗？当你再拿出两本书时又会怎样？</p><p>你是否拥有一个系统，来减轻维护个人藏书库所带来的精神成本？</p><p>你是否已经充分使用过这个系统，从而能够发现问题、解决问题，并将该系统深深烙印在你大脑的神经网络中——甚至达到了成为习惯的程度？</p><p>书籍可能最终散落在你房子的不同房间里，你的书架变得杂乱无章。</p><p>如果没有一个给意识建立秩序的好系统，整理书架所需不断增长的能量将会导致焦虑、不知所措和压力。</p><p><strong>这与专注工作和生产力有什么关系？</strong></p><p>如果你不把通向成功的道路系统化，你就无法获得成功。</p><p>你的生产力系统是随着时间推移你将使其变得更高效的众多系统之一。</p><p>生产力的核心是尽可能快地从A点到达B点。</p><p>就像你家里的书架一样，如果你的工作没有一个系统，你就会被眼前的任务压得喘不过气来。</p><p>当你不知所措时，如果你的大脑没有一个系统，那种不知所措的强度就会增加。</p><p>既然熵已经死死抓住了你的生产力，它就可能会导致长达一周的情绪和惰性下行螺旋……没人想要那样的结果。</p><h2 id="_4小时哲学——我的专注工作10大戒律" tabindex="-1">4小时哲学——我的专注工作10大戒律 <a class="header-anchor" href="#_4小时哲学——我的专注工作10大戒律" aria-label="Permalink to &quot;4小时哲学——我的专注工作10大戒律&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>人类在概念层面上生存。</p><p>我们渴望建立系统，以使我们创造的心理构建存活下来——“自我”便是其中之一。</p><p>我们依附于一个概念，把它变成我们身份认同的一部分，这同时也就为痛苦敞开了大门。</p><p>这并不总是一件坏事。</p><p>你有一个自我。</p><p>你有一个小我（ego）。</p><p>除非你打算出家当和尚（从我读到的资料来看，他们依然要经历类似的世俗挣扎……我们永远无法进入他们的精神境界，所以谁知道呢。最好还是自己去实验），否则我们就必须利用这些知识来发挥我们的优势。</p><p>如果你能大致认同一种积极版本的成功，以及那些能带你走向成功的项目：</p><p><em>你就会渴望建立系统，来帮助这些概念存活下来。</em></p><p>如果你为你的未来创造了一个愿景，你就会潜意识地努力让那个愿景存活下来。</p><p>如果你创建了一个能帮助你实现该愿景的项目，你就会努力让那个项目存活下来。</p><p>如果你创造了一个能够每天自动决定花4小时去建设那个项目的身份认同，你就会努力让那个身份认同存活下来。</p><p>为什么？因为如果你不能让你之所以为“你”的那些东西存活下来……那么你就不复存在了。</p><p>“死亡”这个我们无法体验的概念，让我们充满了恐惧。</p><p>我们要么能转化那种恐惧，要么就成为它的奴隶。</p><p>所以，让我们用一种元方法（meta approach）来看待生产力。</p><p>通过以下步骤，你可以开始打造一个生产力系统，让你能够实现你的成功愿景。</p><p><strong>1) 为什么是4小时？</strong></p><p>概念系统需要精神能量才能蓬勃发展。</p><p>从个人经验、科学研究以及我在生产力领域混迹时听到的轶事来看……3到4小时是消耗精神能量的绝佳甜点区。</p><p>有些研究表明5到6小时是上限。</p><p>但是，3到4小时的极度专注为你的工作创造了一个截止日期，这会进一步收拢你的注意力，并有助于抑制分心。</p><p>先以4小时为目标开始。</p><p><strong>2) 愿景与身份认同</strong></p><p>这是留给另一封信的话题，而且我们之前也讨论过，但你需要一个 MVV。</p><p>最小可行愿景（Minimum Viable Vision）。</p><p>你在第一次尝试时不会对它有绝对清晰的认识。</p><p>写下以下内容（尽可能具体详细）：</p><ul><li>你想成为谁</li><li>你想做什么工作</li><li>你想住在哪里</li><li>你理想的一天是什么样子</li><li>你将如何为人类做出贡献</li><li>你希望周围都是些什么样的人（人脉和社交圈）</li></ul><p>通过回答脑海中涌现出的更多问题，随心所欲地让这种意识流延续下去。</p><p>当你的行动开始习惯性地与你的愿景保持一致时，你的人格发展也就水到渠成了。</p><p><strong>3) 勾勒3个拉动杠杆的任务</strong></p><p>这取决于具体情况。</p><p>你必须对业务发展到下一阶段所需的任务有一个全局观的了解。</p><p>作为一名创作者，阅读这篇<a href="https://thedankoe.com/the-one-person-business-roadmap-99-of-creators-make-this-mistake/" target="_blank" rel="noreferrer">一人企业（One Person Business）路线图</a>，了解作为初级、中级或高级玩家应该执行什么</p><p>以下是我在当前业务阶段的杠杆拉动项：</p><ol><li><strong>创作内容</strong> —— 我每天早晨都会写我的时事通讯。这些文字会被拆解并重新利用到各大平台（这包含在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中，一个<em>高效的</em>内容创作系统）。</li><li><strong>带来流量</strong> —— 当你在某个平台刚起步时，增长不是自动发生的。因为我在 LinkedIn 上的受众最少，所以我会主动与人建立联系，让更多人看到我的内容。</li><li><strong>推广我的产品</strong> —— 随着各大平台有了稳定的流量，我每天都会直接或间接地推广一次我的报价（<em>所有</em>这 3 项内容都在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中系统化了）。</li></ol><p>这就确保了我的企业能够持续增长，并带来可持续的销售收入。</p><p><img src="'+a+'" alt=""></p><p>给这些任务加上一个具体的数字也很有帮助，比如“写 1000 字”。</p><p>我每天早晨写时事通讯的 1 个章节。我清楚地知道该给谁发消息和私信。我每天推广 1 次我的产品。</p><p>在我的大脑看来，这些都是可量化的。</p><p><em>根据你的愿景、商业模式和经验水平，哪些可量化的任务能带来最大的进展？</em></p><p><strong>4) 理清这些任务</strong></p><p>每周要有那么几次，你必须用产生清晰度的任务来替换撬动杠杆的任务。</p><p>每个周日和周一，我把写时事通讯的时间换成做大纲和研究。</p><p>在下午，我会消费围绕我兴趣点的内容。这是为了激发创意。</p><p>在晚上（有时是早晨），我会准确地列出我要完成的事情的大纲。当我醒来时，我的大脑就已经专注于那个计划了。</p><p>我在我的<a href="https://thedankoe.com/the-3-part-daily-routine-for-maximum-productivity/" target="_blank" rel="noreferrer">填充-清空-使用框架（Fill Empty Use framework）</a>中谈到过这种平衡。</p><p>有了系统化的好主意供应，我在构思大纲和撰写时事通讯时就不会遇到任何阻力。</p><p><em>你该如何利用每周的 1-2 小时，为自己安排无缝衔接的工作时段？</em></p><p><strong>5) 时间块与休息</strong></p><p>一开始，在它成为习惯之前，把这些时间块加进你的日历并设置提醒。</p><p>这是你可以测试的东西。</p><p>我发现，90 分钟的专注加上 15-30 分钟的休息，对我来说是绝佳的甜点区。</p><p>在这段时间里，我会处理我的优先任务，然后去短暂散个步，接着直接回到工作中再干 90 分钟。</p><p>如果愿意，你可以把这些 90 分钟的时间块安排在一整天里。</p><p>但是，请注意，当整个世界都醒着的时候，干扰会多得多。</p><p><strong>6) 操控截止日期</strong></p><p>截止日期能收窄你的注意力。</p><p>狭窄的注意力（集中在一个你清楚该如何实现的结果上）能增加进入心流的可能性。</p><p>心流状态就像是专注工作的氮气加速器。</p><p>总共 4 小时的工作和 90 分钟的时间块也许能搞定任务，但你可以进一步约束你的注意力。</p><p>把一些实实在在的东西押上去，并让所有人知道。</p><p>如果我设定了产品发布的日期并接受了预售付款，那么与产品发布相关的任何事情<em>绝对不可能</em>做不完。</p><p>发挥创意。<em>你该如何为你的工作增加一个真实的截止日期？</em> 它可以是长期的，也可以是短期的。</p><p><strong>7) 操控环境</strong></p><p>你的环境必须有利于你的工作时段。</p><p>工作前，我对起床后要做的事情有精确的步骤：</p><ul><li>刷牙和洗澡</li><li>遛狗并喂狗</li><li>冲咖啡，然后写作</li></ul><p>这有助于减少在工作开始前的决策疲劳和分心的可能。</p><p>在工作时，我的环境是经过精心布置的，以收窄我对眼前任务的专注：</p><ul><li>整洁的办公区</li><li>好用的耳机和无歌词的音乐（比如回响贝斯，其复杂性也能通过“屏蔽干扰”和不去留意歌曲本身来收窄注意力）</li><li>没有任何实体物品——比如我的手机或备忘录——会打断我的注意力。</li></ul><p><em>你如何操控环境，以为你的优先任务保存脑力？</em></p><p><strong>8) 在干扰出现前醒来</strong></p><p>干扰是你生产力系统开始熵增的源头。</p><p>你给干扰越多渗透进你意识的机会，你就越有可能陷入拖延的向下螺旋。</p><p>这是我最有效的生产力建议：</p><p><em>早起 1-2 小时。</em></p><p>哪怕你是个夜猫子（利用你那困倦却开放专注的大脑来做创造性工作，而不是技术性工作）。</p><p>即便你被<em>允许</em>忽略消息，不碰手机……</p><p>没有人会给你发短信、打电话，或者试图联系你。单是这一点就能对冲掉被卷入社交软件的风险。因为你的手机不需要你的关注。</p><p><strong>9)</strong> <strong>优先</strong> <strong>休息</strong></p><p>没有高质量的休息，就不可能有高质量的工作。就这么简单。</p><p>但正如我们在关于平衡日常作息的时事通讯中所讨论的那样：</p><p>“休息”并不意味着看 Netflix、喝红酒和泡泡浴。</p><p>休息 = 通过与工作无关的活动来恢复精神能量，例如：</p><ul><li>去健身房</li><li>去散步</li><li>和朋友社交</li><li>读一本好书</li><li>尝试一项新爱好</li></ul><p>任何不助长平庸或廉价多巴胺习惯的事情都可以。</p><p>与此相关的另一件重要的事情是：</p><p>当你这 4 小时的工作时间结束时，停止工作。</p><p>完全停下来。没有任何借口。</p><p>打破那种<em>必须</em>加班超出你规定时间的习惯。</p><p>如果你停不下来，因为一停你的业务就会崩溃，那就是个问题了。</p><p>去解决它（用系统来解决）。</p><p><strong>10) 让你的系统更高效</strong></p><p>如果你的工作多到无法将工作时间控制在 4 小时以内（假设你想这样做），那么同样的，这是个问题。</p><p>解决问题需要创造力和系统化。</p><p>换句话说，这也是优先休息的另一个原因，这样你大脑中的默认模式网络就能帮忙解决问题。</p><p>你必须实施解决方案，随着时间推移去测试并优化。</p><p>如果因为客户的工作，我无法在 4 小时内完工，那我就必须：</p><ul><li>建立更庞大的受众群体</li><li>创造一款不需要占用我时间的产品</li><li>推广并改进那款产品直到可持续</li><li>利用我新获得的空闲时间，少接一些客户</li></ul><p>你可能会觉得这不会立竿见影，没错。多点耐心。</p><p>那么，最后一个问题：</p><p>是什么阻止了你每天只工作 4 小时，你能做些什么来改变这一点？</p><p>在能够更聪明地工作之前，你必须更努力地工作。</p><p>在你完全不再把它当成工作之前，你必须更聪明地工作。</p><p><strong>11) 额外福利：运用数字工具</strong></p><p>一旦你有钱投资于自动化软件，你就应该去投。</p><p>用 TweetHunter 这样的软件批量定时发布内容。</p><p>在 Notion 中写出、组织并完善你的系统。</p><p>当问题出现时，比如处理邮件花了太多时间，去寻找关于如何腾出这段时间的具体知识——不要仅仅只是听天由命。</p><p><em>与其让自己分心，不如针对你最紧迫的问题去<strong>学习</strong>。</em></p><p><strong>我给你的挑战</strong></p><p>写下这些准则，然后去执行。</p><p>不要光读不练，要把这些信息应用起来。</p><p>对于那些朝着这个方向打造自己生活方式的人来说，4 小时工作制绝对是可能的。</p><p>如果你充分发挥互联网的潜力（而不是让它利用你），它就是一个不可思议的工具。</p><p>—— Dan Koe</p><p><strong>本周动态</strong></p><p>Digital Economics 现已向公众开放。你可以随时注册。<em>而且，你可以免费访问 Digital Economics 101</em>。如果你有兴趣用我这 3 年创作者（creator）经验打磨出的<em>系统</em>将你自己产品化，可以考虑加入。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">了解 Digital Economics。</a></p><p>如果你只想要内容系统（比如我是如何创作时事通讯 &gt; 长推文 &gt; 以及可重复利用的推文的），请注册 2 Hour Writer。这是 Digital Economics 的一部分（如果你之后想升级，里面有一张折扣码，可以抵扣掉这门课的价格）。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">注册 2 Hour Writer。</a></p><p>在 Modern Mastery 中，我为那些觉得必须死磕一件事的人发布了一项关于如何“将多重兴趣确定细分领域（niche down）”的培训。Joey 也发布了“如何重新掌控你的神经系统”以实现最佳表现的分享。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需 5 美元即可加入。</a></p><hr><p><a href="/en/letters/the-4-hour-workday-focused-work-changed-my-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',214))])}const D=i(g,[["render",d]]);export{T as __pageData,D as default};
